22	export default async function LeasesPage({
23	  searchParams,
24	}: {
25	  searchParams: Promise<{ q?: string | string[] }>;
26	}) {
27	  const userId = await getUserId();
28	  if (!userId) redirect("/login");
29	
30	  const caller = await loadCaller(userId);
31	  // UX redirect only: listLeases and getLease re-check the caller's role and org (R36).
32	  if (!caller.member) {
33	    if (caller.tenantIds.length > 0) redirect("/tenant");
34	    redirect("/");
35	  }
36	
37	  const { q: rawQ } = await searchParams;
38	  const q = (Array.isArray(rawQ) ? rawQ[0] : rawQ)?.trim() ?? "";
39	  return (
40	    <>
41	      <StaffNav active="/leases" />
