71	async function LeaseTable({ userId, q }: { userId: string; q: string }) {
72	  const all = await listLeases({ userId });
73	  // Server-side search on unit or tenant name (bonus R56), case-insensitive substring.
74	  const needle = q.toLowerCase();
75	  const leases =
76	    needle === ""
77	      ? all
78	      : all.filter(
79	          (l) => l.unitName.toLowerCase().includes(needle) || l.tenantName.toLowerCase().includes(needle),
80	        );
81	
82	  return (
83	    <Card>
84	      <CardContent>
85	        {leases.length === 0 ? (
86	          <p className="rounded-lg border border-dashed p-8 text-center text-sm text-muted-foreground">
87	            {q === ""
88	              ? "There are no leases in your organisation yet."
89	              : `No lease matches "${q}". Try a different unit or tenant name.`}
90	          </p>
91	        ) : (
92	          <Table>
93	            <TableHeader>
94	              <TableRow>
95	                <TableHead>Unit</TableHead>
96	                <TableHead>Tenant</TableHead>
97	                <TableHead>Start</TableHead>
98	                <TableHead>End</TableHead>
99	                <TableHead className="text-right">Monthly rent</TableHead>
100	                <TableHead className="text-right">
101	                  <span className="sr-only">Open</span>
102	                </TableHead>
103	              </TableRow>
104	            </TableHeader>
105	            <TableBody>
106	              {leases.map((l) => (
107	                <TableRow key={l.id}>
108	                  <TableCell className="font-medium">{l.unitName}</TableCell>
109	                  <TableCell>{l.tenantName}</TableCell>
110	                  <TableCell className="tabular-nums">{l.startDate}</TableCell>
111	                  <TableCell className="tabular-nums">{l.endDate}</TableCell>
112	                  <TableCell className="text-right tabular-nums">{formatSen(l.monthlyRentSen)}</TableCell>
113	                  <TableCell className="text-right">
114	                    <Link
115	                      href={`/leases/${l.id}`}
116	                      className="text-sm font-medium underline-offset-4 hover:underline"
117	                    >
118	                      View
119	                    </Link>
120	                  </TableCell>
121	                </TableRow>
122	              ))}
123	            </TableBody>
124	          </Table>
125	        )}
126	      </CardContent>
127	    </Card>
128	  );
129	}
