28	const REPORT_MONTHS = 6;
29	
30	// "YYYY-MM" shifted by a whole number of months; integer month math, no Date (R3/R52).
31	function shiftMonth(ym: string, delta: number): string {
32	  const index = Number(ym.slice(0, 4)) * 12 + (Number(ym.slice(5, 7)) - 1) + delta;
33	  const y = Math.floor(index / 12);
34	  const m = (index % 12) + 1;
35	  return `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}`;
36	}
