38	export default async function DashboardPage() {
39	  const userId = await getUserId();
40	  if (!userId) redirect("/login");
41	
42	  const caller = await loadCaller(userId);
43	  // UX redirect only: the services re-check the role themselves (R36).
44	  if (!caller.member) {
45	    if (caller.tenantIds.length > 0) redirect("/tenant");
46	    return (
47	      <Card className="max-w-md">
48	        <CardHeader>
49	          <CardTitle>No access</CardTitle>
50	          <CardDescription>This account is not linked to an organisation.</CardDescription>
51	        </CardHeader>
52	      </Card>
53	    );
54	  }
55	
56	  return (
57	    <>
58	      <StaffNav active="/dashboard" />
59	      <h1 className="mb-6 text-2xl font-semibold tracking-tight">Dashboard</h1>
60	      <Suspense fallback={<DashboardSkeleton />}>
61	        <DashboardBody userId={userId} />
62	      </Suspense>
63	    </>
