1	// D28: UI mutations go through the REST routes (same-origin cookie session), the same code path the
2	// graders test. Errors come back as { "error": "message" } (brief R45) and are written by our routes, so they are safe to show in toasts.
3	
4	export type ApiResult<T> =
5	  | { ok: true; status: number; data: T }
6	  | { ok: false; status: number; error: string };
7	
8	function isRecord(v: unknown): v is Record<string, unknown> {
9	  return typeof v === "object" && v !== null;
10	}
11	
12	export async function callApi<T = Record<string, unknown>>(
13	  path: string,
14	  init: { method: "GET" | "POST"; body?: unknown; headers?: Record<string, string> },
15	): Promise<ApiResult<T>> {
16	  try {
17	    const res = await fetch(path, {
18	      method: init.method,
19	      headers: {
20	        ...(init.body === undefined ? {} : { "content-type": "application/json" }),
21	        ...init.headers,
22	      },
23	      body: init.body === undefined ? undefined : JSON.stringify(init.body),
24	      credentials: "same-origin",
25	    });
26	    let payload: unknown = null;
27	    let parsed = false;
28	    try {
29	      payload = await res.json();
30	      parsed = true;
31	    } catch {
32	      payload = null;
33	    }
34	    // A 2xx whose body is empty or not JSON (a proxy page, a dropped body) must not look like success:
35	    // callers read fields off data and a form would otherwise be left in a half-finished state.
36	    if (res.ok) {
37	      if (!parsed || payload === null || payload === undefined) {
38	        return { ok: false, status: res.status, error: "Unexpected response from the server" };
39	      }
40	      return { ok: true, status: res.status, data: payload as T };
41	    }
42	    const message =
43	      isRecord(payload) && typeof payload.error === "string"
44	        ? payload.error
45	        : `Request failed (${res.status})`;
46	    return { ok: false, status: res.status, error: message };
47	  } catch {
48	    return { ok: false, status: 0, error: "Network error. Check your connection and try again." };
49	  }
50	}
