21	const SLIP_BUCKET = "payment-slips";
22	const MAX_SLIP_BYTES = 5 * 1024 * 1024; // R20: at most 5 MB (the bucket enforces the same limit)
23	const SLIP_EXT: Record<string, string> = {
24	  "image/jpeg": "jpg",
25	  "image/png": "png",
26	  "application/pdf": "pdf",
27	};
28	
29	type Method = "cash" | "bank_transfer";
30	const METHOD_ITEMS: { value: Method; label: string }[] = [
31	  { value: "cash", label: "Cash" },
32	  { value: "bank_transfer", label: "Bank transfer" },
33	];
34	
35	type FieldErrors = { amount?: string; receivedAt?: string; slip?: string };
36	
37	// "Now" as a datetime-local value in Malaysia time. The page computes the initial value on the server and
38	// passes it in, so server and client render the same string (no hydration mismatch); the reset after a
39	// successful submit uses the same helper.
40	function nowInMytLocal(): string {
41	  return formatInstantMyt(new Date()).slice(0, 16);
42	}
43	
44	const SLIP_UPLOAD_ERROR = "Slip upload failed. Use a JPEG, PNG or PDF of at most 5 MB.";
45	
46	function validateSlip(file: File | null): string | undefined {
47	  if (!file) return "Attach the bank transfer slip (JPEG, PNG or PDF).";
48	  if (!(file.type in SLIP_EXT)) return "The slip must be a JPEG, PNG or PDF file.";
49	  if (file.size > MAX_SLIP_BYTES) return "The slip must be 5 MB or smaller.";
50	  return undefined;
51	}
