53	type Props = { leaseId: string; orgId: string; isManager: boolean; defaultReceivedAt: string };
54	
55	export function RecordPaymentForm({ leaseId, orgId, isManager, defaultReceivedAt }: Props) {
56	  const router = useRouter();
57	  const [amount, setAmount] = useState("");
58	  const [method, setMethod] = useState<Method>("cash");
59	  const [receivedAt, setReceivedAt] = useState(defaultReceivedAt);
60	  const [file, setFile] = useState<File | null>(null);
61	  const [errors, setErrors] = useState<FieldErrors>({});
62	  const [submitting, setSubmitting] = useState(false);
63	  const fileRef = useRef<HTMLInputElement>(null);
64	  // D9: one optional Idempotency-Key per form render protects against a double click; a new one after success.
65	  const keyRef = useRef<string | null>(null);
66	
67	  function onAmountChange(value: string) {
68	    setAmount(value);
69	    if (errors.amount) setErrors((e) => ({ ...e, amount: undefined }));
70	  }
71	
72	  function validate(): { amountSen: number; receivedAtIso: string } | null {
73	    const next: FieldErrors = {};
74	    let amountSen = 0;
75	    try {
76	      amountSen = parseRinggitToSen(amount);
77	      if (!Number.isSafeInteger(amountSen)) throw new Error("too large");
78	      if (amountSen <= 0) next.amount = "The amount must be greater than zero.";
79	    } catch {
80	      next.amount = "Enter an amount like 1,500.00";
81	    }
82	    let receivedAtIso = "";
83	    if (!receivedAt) {
84	      next.receivedAt = "Choose when the payment was received (Malaysia time).";
85	    } else {
86	      try {
87	        receivedAtIso = mytLocalToIso(receivedAt);
88	      } catch {
89	        next.receivedAt = "Enter a valid date and time (Malaysia time).";
90	      }
91	    }
92	    if (method === "bank_transfer") {
93	      const slipError = validateSlip(file);
94	      if (slipError) next.slip = slipError;
95	    }
96	    setErrors(next);
97	    return Object.keys(next).length === 0 ? { amountSen, receivedAtIso } : null;
98	  }
99	
100	  async function onSubmit(e: FormEvent<HTMLFormElement>) {
101	    e.preventDefault();
102	    if (submitting) return;
103	    const valid = validate();
104	    if (!valid) return;
105	
106	    setSubmitting(true);
107	    const supabase = createClient();
108	    let slipPath: string | undefined;
109	
110	    try {
111	      if (method === "bank_transfer" && file) {
112	        // R44: path <org_id>/<lease_id>/<uuid>.<ext>; Storage RLS only lets this org's staff upload here.
113	        slipPath = `${orgId}/${leaseId}/${crypto.randomUUID()}.${SLIP_EXT[file.type]}`;
114	        const { error } = await supabase.storage
115	          .from(SLIP_BUCKET)
116	          .upload(slipPath, file, { contentType: file.type, upsert: false });
117	        if (error) {
118	          // Fixed text: Storage error messages are internal and not for end users.
119	          toast.error(SLIP_UPLOAD_ERROR);
120	          slipPath = undefined;
121	          return;
122	        }
123	      }
124	
125	      keyRef.current ??= crypto.randomUUID();
126	      const res = await callApi<{ id: string; status: string }>(`/api/leases/${leaseId}/payments`, {
127	        method: "POST",
128	        headers: { "Idempotency-Key": keyRef.current },
129	        body: {
130	          amountSen: valid.amountSen,
131	          method,
132	          receivedAt: valid.receivedAtIso,
133	          ...(slipPath ? { slipPath } : {}),
134	        },
135	      });
136	
137	      if (!res.ok) {
138	        toast.error(res.error);
139	        if (slipPath) {
140	          // R20: the server removes the orphan slip itself; this is a best-effort second attempt (the
141	          // browser role has no DELETE policy, so it may be refused, which is fine).
142	          await supabase.storage.from(SLIP_BUCKET).remove([slipPath]).catch(() => undefined);
143	        }
144	        return;
145	      }
146	
147	      toast.success(
148	        res.data.status === "approved"
149	          ? `Payment of ${formatSen(valid.amountSen)} recorded and approved.`
150	          : `Payment of ${formatSen(valid.amountSen)} recorded. It waits for a manager's approval.`,
151	      );
152	      keyRef.current = null;
153	      setAmount("");
154	      setFile(null);
155	      setErrors({});
156	      if (fileRef.current) fileRef.current.value = "";
157	      setReceivedAt(nowInMytLocal());
158	      router.refresh();
159	    } catch {
160	      toast.error("Something went wrong. Please try again.");
161	    } finally {
162	      setSubmitting(false);
163	    }
164	  }
165	
166	  return (
167	    <form onSubmit={onSubmit} noValidate className="grid gap-4 sm:grid-cols-2">
168	      <div className="flex flex-col gap-2">
169	        <Label htmlFor="amount">Amount (RM)</Label>
170	        <Input
171	          id="amount"
172	          inputMode="decimal"
173	          autoComplete="off"
174	          placeholder="1,500.00"
175	          value={amount}
176	          onChange={(e) => onAmountChange(e.target.value)}
177	          aria-invalid={Boolean(errors.amount)}
178	          aria-describedby={errors.amount ? "amount-error" : undefined}
179	          disabled={submitting}
180	        />
181	        {errors.amount && (
182	          <p id="amount-error" className="text-sm text-destructive">
183	            {errors.amount}
184	          </p>
185	        )}
186	      </div>
187	
188	      <div className="flex flex-col gap-2">
189	        <Label htmlFor="method">Method</Label>
190	        <Select
191	          value={method}
192	          items={METHOD_ITEMS}
193	          onValueChange={(v) => {
194	            if (v === "cash" || v === "bank_transfer") {
195	              setMethod(v);
196	              setErrors((e) => ({ ...e, slip: undefined }));
197	            }
198	          }}
199	          disabled={submitting}
200	        >
201	          <SelectTrigger id="method" className="w-full">
202	            <SelectValue />
203	          </SelectTrigger>
204	          <SelectContent>
205	            {METHOD_ITEMS.map((m) => (
206	              <SelectItem key={m.value} value={m.value}>
207	                {m.label}
208	              </SelectItem>
209	            ))}
210	          </SelectContent>
211	        </Select>
212	      </div>
213	
214	      <div className="flex flex-col gap-2">
215	        <Label htmlFor="received-at">Received at (Malaysia time)</Label>
216	        <Input
217	          id="received-at"
218	          type="datetime-local"
219	          value={receivedAt}
220	          onChange={(e) => {
221	            setReceivedAt(e.target.value);
222	            if (errors.receivedAt) setErrors((er) => ({ ...er, receivedAt: undefined }));
223	          }}
224	          aria-invalid={Boolean(errors.receivedAt)}
225	          aria-describedby={errors.receivedAt ? "received-at-error" : undefined}
226	          disabled={submitting}
227	        />
228	        {errors.receivedAt && (
229	          <p id="received-at-error" className="text-sm text-destructive">
230	            {errors.receivedAt}
231	          </p>
232	        )}
233	      </div>
234	
235	      {method === "bank_transfer" && (
236	        <div className="flex flex-col gap-2">
237	          <Label htmlFor="slip">Bank transfer slip (JPEG, PNG or PDF, up to 5 MB)</Label>
238	          <Input
239	            id="slip"
240	            ref={fileRef}
241	            type="file"
242	            accept="image/jpeg,image/png,application/pdf"
243	            onChange={(e) => {
244	              const f = e.target.files?.[0] ?? null;
245	              setFile(f);
246	              setErrors((er) => ({ ...er, slip: f ? validateSlip(f) : undefined }));
247	            }}
248	            aria-invalid={Boolean(errors.slip)}
249	            aria-describedby={errors.slip ? "slip-error" : undefined}
250	            disabled={submitting}
251	          />
252	          {errors.slip && (
253	            <p id="slip-error" className="text-sm text-destructive">
254	              {errors.slip}
255	            </p>
256	          )}
257	        </div>
258	      )}
259	
260	      <div className="flex flex-col gap-2 sm:col-span-2 sm:flex-row sm:items-center sm:justify-between">
261	        <p className="text-sm text-muted-foreground">
262	          {isManager
263	            ? "Payments you record are approved immediately."
264	            : "Payments you record wait for a manager's approval."}
265	        </p>
266	        <Button type="submit" disabled={submitting}>
267	          {submitting ? "Recording..." : "Record payment"}
268	        </Button>
269	      </div>
270	    </form>
271	  );
272	}
