"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";

export type NavLink = { href: string; label: string };

// Which links to show is decided on the server from the caller's DB role (see AppHeader); this component
// only highlights the current section. It is navigation, not authorization: every page re-checks access.
export function HeaderNav({ links }: { links: NavLink[] }) {
  const pathname = usePathname();
  if (links.length === 0) return null;
  return (
    <nav aria-label="Main navigation" className="flex items-center gap-1">
      {links.map((l) => {
        const active = pathname === l.href || pathname.startsWith(`${l.href}/`);
        return (
          <Link
            key={l.href}
            href={l.href}
            aria-current={active ? "page" : undefined}
            className={cn(
              "rounded-md px-3 py-1.5 text-sm font-medium transition-colors",
              active ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground",
            )}
          >
            {l.label}
          </Link>
        );
      })}
    </nav>
  );
}

import Link from "next/link";
import { loadCaller } from "@/server/access";
import { getUserId } from "@/server/auth";
import { HeaderNav, type NavLink } from "./header-nav";
import { SignOutButton } from "./sign-out-button";

// Links follow the DB role (memberships / tenants.user_id), never user_metadata. If the lookup fails the
// header still renders, just without links.
async function navLinks(): Promise<NavLink[]> {
  try {
    const userId = await getUserId();
    if (!userId) return [];
    const caller = await loadCaller(userId);
    const links: NavLink[] = [];
    if (caller.member) {
      links.push({ href: "/dashboard", label: "Dashboard" }, { href: "/leases", label: "Leases" });
    }
    if (caller.tenantIds.length > 0) links.push({ href: "/tenant", label: "My tenancy" });
    return links;
  } catch {
    return [];
  }
}

export async function AppHeader({ email }: { email: string }) {
  const links = await navLinks();
  return (
    <header className="border-b bg-background">
      <div className="mx-auto flex h-14 w-full max-w-6xl items-center justify-between gap-4 px-4">
        <div className="flex min-w-0 items-center gap-4">
          <Link href="/" className="shrink-0 text-base font-semibold tracking-tight">
            Rent Collection
          </Link>
          <HeaderNav links={links} />
        </div>
        <div className="flex min-w-0 items-center gap-3">
          <span className="hidden truncate text-sm text-muted-foreground sm:inline">{email}</span>
          <SignOutButton />
        </div>
      </div>
    </header>
  );
}

const LINKS = [
  { href: "/dashboard", label: "Dashboard" },
  { href: "/leases", label: "Leases" },
] as const;

// The Dashboard / Leases links now live in the app header (HeaderNav). The component stays so existing
// pages keep compiling; rendering it as well would show the same links twice.
export function StaffNav(_props: { active: (typeof LINKS)[number]["href"] }) {
  return null;
}

// The Dashboard / Leases links now live in the app header (HeaderNav). The component stays so existing
// pages keep compiling; rendering it as well would show the same links twice.
export function StaffNav(props: { active: "/dashboard" | "/leases" }) {
  void props;
  return null;
}

